contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Set up: initialize MinSum (only once, before Initialized).
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        // Deposit msg.sender's balance.
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Read before-values through the public surface.
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;

        // Make the deciding Collect call.
        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // Read after-values.
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;

        // General rule: when caller's balance meets MinSum and collectAmount ≤ that balance,
        // Collect must succeed and must decrease both the recorded balance and c's Ether
        // balance by exactly collectAmount.
        assert(!(beforeBal >= minSum && collectAmount <= beforeBal) ||
               (!reverted && afterBal == beforeBal - collectAmount && afterC == beforeC - collectAmount));
    }

    receive() external payable {}
}

